import {reviewItems,sourceFileIndex} from './review-model.js';
import {prepareEvidence,syntheticObservations,units} from './evidence.js';
import {extraAttributes,ruleFields,validateRule,evaluateRules,policyOutcome,validateBundle,trustSummary,gateChecks} from './governance.js';
import {profiles,rules,eligible,mockML,mockEvidence,mockContext,referral} from './engine.js';
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let profile={...profiles[0]},mode='mock',view='workbench',files=[],run=null,busy=false,controller=null,apiStatus=null;
let selectedEvidence=null,reviewTab='issues',showScenarioSelection=false;
const reviewUrls=new Map();
let evidenceScenario='as_declared';
let customRules=[],customInstructions='',policyRevision=1,editingRule=null;
const events=[],stages=[['intake','Application & input guardrails'],['ml','Historical ML risk screening'],['evidence','Vision LLM · evidence understanding'],['context','Internal, external & knowledge retrieval'],['reason','Reasoning harness · bounded revision'],['verify','Output guardrails & business rules'],['decision','Assessment outcome']];
function log(action,detail){events.unshift({time:new Date().toISOString(),profile:profile.name,mode,action,detail});}
function badge(s,color='blue'){return `<span class="badge ${color}">${esc(s)}</span>`}
function toast(s){$('#toast').textContent=s;$('#toast').classList.add('show');setTimeout(()=>$('#toast').classList.remove('show'),4000)}
function reset(){showScenarioSelection=false;for(const url of reviewUrls.values())URL.revokeObjectURL(url);reviewUrls.clear();selectedEvidence=null;reviewTab='issues';run=null;log('Assessment invalidated','Inputs or mode changed.');}
function render(){const labels={workbench:'Assessment studio',flow:'Hybrid architecture',rules:'Rules & guardrails',settings:'Local API setup',audit:'Audit trail',research:'Research & design'};$('#crumb').textContent=labels[view];document.querySelectorAll('nav button').forEach(b=>b.classList.toggle('active',b.dataset.view===view));$('#app').innerHTML=view==='workbench'?studio():view==='flow'?architecture():view==='rules'?advancedRulesView():view==='research'?researchView():view==='settings'?settings():audit();bind();bindGovernance();bindReviewWorkspace()}
function options(values,current){return values.map(x=>`<option ${x===current?'selected':''}>${esc(x)}</option>`).join('')}
function legacyStudio(){return `<div class="page-title"><div><span class="eyebrow">HYBRID AI UNDERWRITING</span><h1>Underwriting workbench</h1><p class="muted">Choose a case, assess the evidence and review the recommendation.</p></div><div class="mode-switch" role="group" aria-label="Assessment mode"><button data-mode="mock" class="${mode==='mock'?'active':''}" ${busy?'disabled':''}>Mock AI demo</button><button data-mode="local" class="${mode==='local'?'active':''}" ${busy?'disabled':''}>Local API testing</button></div></div><div class="mode-notice">${mode==='mock'?'● SIMULATION · Fictional profiles, scripted AI outputs and synthetic documents. Uploaded content is not analysed.':'● LOCAL API · Real model calls through your local runner. No silent fallback to mock results.'}</div><div class="hybrid-grid"><section class="panel profile-panel"><div class="section-heading"><h2>Customer profile</h2>${badge('01 · INPUT')}</div><label>Choose a demo journey<select id="profile" ${busy?'disabled':''}>${profiles.map(p=>`<option value="${p.id}" ${p.id===profile.id?'selected':''}>${p.name} — ${p.title}</option>`).join('')}</select></label><div class="profile-summary"><div class="person-avatar">${esc(profile.name.split(' ').map(s=>s[0]).join(''))}</div><div><h2>${esc(profile.name)}</h2><p>${esc(profile.occupation)} · ${profile.age} years</p></div></div><form id="profile-form"><fieldset ${busy?'disabled':''}><div class="form-grid"><label>Product<select name="product">${options(['Life','Medical'],profile.product)}</select></label><label>Age<input name="age" required type="number" min="18" max="100" value="${profile.age}"></label><label>Sex (demographic)<select name="sex">${options(['Male','Female','Not specified'],profile.sex)}</select></label><label>Occupation<input name="occupation" required maxlength="80" value="${esc(profile.occupation)}"></label><label>Cover (SGD)<input name="cover" required type="number" min="1000" max="10000000" step="1000" value="${profile.cover}"></label><label>BMI (declared)<input name="bmi" required type="number" min="10" max="70" step=".1" value="${profile.bmi}"></label><label>Smoking<select name="smoker"><option value="false" ${!profile.smoker?'selected':''}>Non-smoker</option><option value="true" ${profile.smoker?'selected':''}>Smoker</option></select></label><label>Medical history<select name="condition">${[['none','No declared conditions'],['controlled','Stable condition'],['complex','Complex history']].map(([v,t])=>`<option value="${v}" ${v===profile.condition?'selected':''}>${t}</option>`).join('')}</select></label></div>${expandedAttributes()}<div class="section-heading"><h3>Supporting documents</h3><span class="muted">${files.length} uploaded</span></div><label class="upload-zone">＋ Add medical reports or blood tests<input id="upload" type="file" multiple accept=".pdf,.png,.jpg,.jpeg,.webp" aria-label="Upload supporting documents"><small>PDF, PNG, JPEG, WebP · 10 MB each · 20 MB total · max 5 files</small></label><div class="file-list">${files.map((f,i)=>`<div><span>▤ ${esc(f.name)} <small>${(f.size/1024).toFixed(0)} KB</small></span><button type="button" data-remove="${i}" aria-label="Remove ${esc(f.name)}">×</button></div>`).join('')}</div>${mode==='mock'?`<label class="check"><input name="evidence" type="checkbox" ${profile.evidence?'checked':''}> Synthetic evidence complete</label><p class="micro">Sample medical report and blood test follow the scenario. Uploaded file content is not read.</p>`:'<p class="micro">Files are sent at execution through the local runner to your Vision LLM. Use test or de-identified records.</p>'}${mode==='mock'?evidenceScenarioPicker():''}${instructionsEditor()}<button class="primary full" type="submit">${busy?'Assessment in progress…':run?'Re-run hybrid assessment ↻':'Run hybrid assessment →'}</button></fieldset></form>${busy?'<button class="secondary full" id="cancel">Cancel assessment</button>':''}</section><div class="assessment-column"><section class="panel pipeline-panel"><div class="section-heading"><div><span class="eyebrow">LIVE EXECUTION</span><h2>Assessment journey</h2></div>${badge(run?.route||'Ready',busy?'amber':'green')}</div><div class="pipeline">${stages.map(([id,title],i)=>{const s=run?.steps[id];return `<div class="pipeline-step ${s?.status||''}"><div class="stage-dot">${s?.status==='done'?'✓':s?.status==='skipped'?'–':s?.status==='error'?'!':String(i+1).padStart(2,'0')}</div><div class="stage-body"><div><strong>${title}</strong><span>${s?.duration_ms!==undefined?(s.duration_ms/1000).toFixed(1)+'s · ':''}${s?.status==='running'?'Running…':s?.status==='done'?'Complete':s?.status==='skipped'?'Skipped':s?.status==='error'?'Stopped':'Pending'}</span></div><p>${esc(s?.summary||stageHint(id))}</p>${s?.data?`<details><summary>Inspect step output</summary><pre>${esc(JSON.stringify(s.data,null,2))}</pre></details>`:''}</div></div>`}).join('')}</div></section>${!run?`<div class="path-preview"><div><span class="eyebrow">FAST PATH</span><h3>ML → standard acceptance</h3><p>High-confidence, in-distribution standard cases pass evidence and business gates.</p></div><div><span class="eyebrow">COMPLEX PATH</span><h3>Vision LLM → reviewed recommendation</h3><p>Exceptions enter evidence extraction, retrieval, bounded reasoning and verification.</p></div></div>`:''}</div></div>`}
function stageHint(id){return ({intake:'Validate customer inputs and document constraints.',ml:'Historical model classification, confidence and out-of-distribution checks.',evidence:'Read reports and images; extract findings and flag evidence gaps.',context:'Internal rules, RAG passages, knowledge relationships and external context.',reason:'Assess evidence against context; revise once if validation fails.',verify:'Check source attribution, output structure and mandatory referral rules.',decision:'Show outcome, reasons, supporting evidence and next actions.'})[id]}
function resultView(){if(!run?.result)return '';const r=run.result;return `<section class="panel result-panel"><div class="section-heading"><span class="eyebrow">ASSESSMENT RESULT</span>${badge(mode==='mock'?'Simulated result':'Local model result',mode==='mock'?'purple':'blue')}</div><div class="decision-banner">${badge(r.status,r.status==='Standard acceptance'?'green':r.status==='Failed'||r.status==='Cancelled'?'red':'amber')}<h2>${esc(r.headline)}</h2><p>${esc(r.explanation)}</p></div><h3>Reasons & explanations</h3>${r.reasons.map(t=>`<div class="reason-line"><span>↳</span><p>${esc(t)}</p></div>`).join('')}${r.sources?.length?`<h3 class="spaced">Evidence & source attribution</h3>${r.sources.map(s=>`<div class="source-card"><code>${esc(s.id)}</code><div><strong>${esc(s.title||s.source)}</strong><p>${esc(s.excerpt||s.text)}</p>${safeLink(s.url)}</div></div>`).join('')}`:''}<div class="note"><strong>Next action</strong><p>${esc(r.next)}</p></div>${r.review&&!busy?`<form id="review-form"><h3>Underwriter review</h3><label>Decision<select name="outcome"><option>Approve standard terms</option><option>Propose revised terms</option><option>Request further evidence</option><option>Postpone</option><option>Decline</option></select></label><label>Decision reason<textarea name="reason" required minlength="10" maxlength="1500" placeholder="Explain the evidence considered and any proposed terms."></textarea></label><button class="primary">Record human decision</button></form>`:''}${r.human?`<div class="note"><strong>Human decision: ${esc(r.human.outcome)}</strong><p>${esc(r.human.reason)}</p></div>`:''}<button class="secondary" id="export-result">Download assessment JSON ↓</button></section>`}
function safeLink(url){try{const u=new URL(url);return ['http:','https:'].includes(u.protocol)?`<a href="${esc(u.href)}" target="_blank" rel="noopener noreferrer">Open source ↗</a>`:''}catch{return ''}}
function architecture(){return `<div class="page-title"><div><span class="eyebrow">TWO PATHS, ONE CONTROLLED PROCESS</span><h1>Hybrid intelligence. Explicit decision gates.</h1><p class="muted">Historical ML screens standard cases. Vision LLM reasoning handles exceptions.</p></div></div><div class="panel flow-panel"><div class="flow-track"><div class="flow-node"><span class="step-number">OFFLINE · MODEL DEVELOPMENT</span><h3>Historical applications & outcomes</h3><p>Curated training data → validation and calibration → model registry. Training is outside this demo; connect your deployed model.</p></div><div class="flow-node"><span class="step-number">01 · INTAKE</span><h3>Profile + supporting evidence</h3><p>Demographics, cover, declarations, medical reports and blood tests. Validate inputs and evidence availability.</p></div><div class="flow-node"><span class="step-number">02 · ML SCREENING</span><h3>Standard-case classifier</h3><p>Class, calibrated confidence and OOD checks. API errors enter the complex path, never automatic approval.</p></div></div><div class="routing">STP GATE<span>Standard + confidence ≥ 0.95 + calibrated + in-distribution + complete evidence + business rules pass</span></div><div class="architecture-paths"><div class="fast-lane"><span class="eyebrow">PASS · STRAIGHT-THROUGH</span><h2>Standard acceptance</h2><p>Record model version, reasons and gate results. Skip expensive reasoning layers.</p></div><div class="complex-lane"><span class="eyebrow">EXCEPTION · DEEPER ASSESSMENT</span><h2>Guarded Vision LLM reasoning</h2><div class="mini-stages"><div><strong>1. Understand evidence</strong><p>Vision extraction with source IDs, uncertainty and evidence gaps.</p></div><div><strong>2. Retrieve context</strong><p>Internal APIs, external data, RAG, OKF / knowledge graph adapters and an optional internet search service.</p></div><div><strong>3. Execute the harness</strong><p>Structured reasoning → citation checks → one revision maximum → guardrails and business rules.</p></div><div><strong>4. Explain & refer</strong><p>Evidence-linked recommendation, missing information and human decision.</p></div></div></div></div></div>`}
function rulesView(){return `<div class="page-title"><div><span class="eyebrow">DEMO POLICY · HYBRID-1.0</span><h1>Make every gate inspectable.</h1><p class="muted">Illustrative controls, not approved insurer or actuarial rules.</p></div></div><div class="panel table-wrap"><table><thead><tr><th>Control</th><th>Layer</th><th>Behaviour</th></tr></thead><tbody>${rules.map(r=>`<tr><td><code>${r[0]}</code></td><td>${r[1]}</td><td>${r[2]}</td></tr>`).join('')}</tbody></table></div><div class="note"><strong>Conservative decision authority in local mode</strong><p>No trained model is bundled. Missing ML integration enters the complex path. Vision LLM output cannot issue a policy or silently approve a referral. Source checks and instruction isolation are not a complete prompt-injection defence.</p></div>`}
function settings(){const local=['localhost','127.0.0.1','[::1]'].includes(location.hostname);return `<div class="page-title"><div><span class="eyebrow">BRING YOUR OWN MODELS</span><h1>Connect your local testing environment.</h1><p class="muted">Keep API keys and service addresses in the Python runner’s environment.</p></div></div><div class="panel setup-panel"><h2>Local runner + your model APIs</h2><p>The hosted demo runs mock mode. For real document testing, open this repository’s local runner on your machine. It serves the same interface and forwards requests to your configured APIs.</p><pre>pip install -r requirements.txt\nexport UW_LLM_BASE_URL=http://localhost:8000/v1\nexport UW_LLM_MODEL=your-vision-model\n# Optional: UW_LLM_API_KEY, UW_ML_URL, UW_CONTEXT_URL\npython server.py\n# Open http://127.0.0.1:8080</pre><p>Use a Vision LLM endpoint supporting OpenAI-compatible chat completions with image inputs. PDF pages are rendered as images. ML and context adapters have documented JSON contracts in the repository.</p><div class="note"><strong>${local?'Local address detected':'You are viewing the hosted demo'}</strong><p>${local?'Check the runner before starting a real assessment.':'Real mode requires the local runner. This hosted page will not access your private network.'}</p></div><button class="primary" id="health" ${!local?'disabled':''}>Check local connection</button>${apiStatus?`<pre>${esc(JSON.stringify(apiStatus,null,2))}</pre>`:''}<div class="setup-grid"><div><h3>Historical ML adapter</h3><p>Returns classification, calibrated confidence, OOD, model version and evidence completeness. Without it, STP is disabled.</p></div><div><h3>Vision LLM</h3><p>Reads images or PDF pages and generates an evidence-linked recommendation. Invalid responses stop or refer the assessment.</p></div><div><h3>Context adapter</h3><p>Connect internal / external data, RAG, OKF, graphs or web search. Return typed, attributable excerpts. No live retrieval is claimed when absent.</p></div><div><h3>Data handling</h3><p>Uploads stay in browser memory until execution and are processed in runner memory. Model and retrieval services may retain requests under their own configuration.</p></div></div></div>`}
function audit(){return `<div class="page-title"><div><span class="eyebrow">SESSION EVENTS</span><h1>Follow the evidence trail.</h1><p class="muted">Events reset on refresh. Download a record of this session.</p></div><button id="export-audit" class="secondary">Export JSON ↓</button></div><div class="panel table-wrap"><table><thead><tr><th>Time</th><th>Profile / mode</th><th>Event</th><th>Detail</th></tr></thead><tbody>${events.length?events.map(e=>`<tr><td>${new Date(e.time).toLocaleTimeString()}</td><td>${esc(e.profile)}<br>${e.mode}</td><td>${esc(e.action)}</td><td>${esc(typeof e.detail==='string'?e.detail:JSON.stringify(e.detail))}</td></tr>`).join(''):'<tr><td colspan="4">Run an assessment to begin the audit trail.</td></tr>'}</tbody></table></div>`}
function download(value,name){const u=URL.createObjectURL(new Blob([JSON.stringify(value,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)}
function bind(){document.querySelectorAll('[data-mode]').forEach(b=>b.onclick=()=>{mode=b.dataset.mode;reset();render()});if($('#profile'))$('#profile').onchange=e=>{profile={...profiles.find(p=>p.id===e.target.value)};files=[];reset();render()};if($('#upload'))$('#upload').onchange=e=>{const add=[...e.target.files];if(files.length+add.length>5||add.some(f=>f.size>10*1024*1024||!['application/pdf','image/png','image/jpeg','image/webp'].includes(f.type))||[...files,...add].reduce((a,f)=>a+f.size,0)>20*1024*1024){toast('Use up to 5 PDF or image files, 10 MB each and 20 MB total.');e.target.value='';return}saveProfile();files.push(...add);reset();render()};document.querySelectorAll('[data-remove]').forEach(b=>b.onclick=()=>{saveProfile();files.splice(+b.dataset.remove,1);reset();render()});if($('#profile-form')){const form=$('#profile-form');form.onchange=e=>{if(e.target.id==='upload')return;if(form.checkValidity())saveProfile();reset();render()};form.onsubmit=e=>{e.preventDefault();saveProfile();start()}}if($('#cancel'))$('#cancel').onclick=()=>controller.abort();if($('#health'))$('#health').onclick=async()=>{try{apiStatus=await api('health',null)}catch(e){apiStatus={error:e.message}}render()};if($('#review-form'))$('#review-form').onsubmit=e=>{e.preventDefault();captureReviewDraft();const f=new FormData(e.target),reason=String(f.get('reason')).trim();if(reason.length<10){toast('Record at least 10 characters of reasoning.');return}run.result.human={outcome:f.get('outcome'),reason};run.result.review=false;log('Human decision',run.result.human);render()};if($('#export-result'))$('#export-result').onclick=()=>download({...run,profile,mode,files:files.map(f=>({name:f.name,size:f.size}))},'hybrid-assessment.json');if($('#export-audit'))$('#export-audit').onclick=()=>download(events,'hybrid-audit.json')}
function saveProfile(){const form=$('#profile-form');if(!form)return;const f=new FormData(form);Object.assign(profile,{product:f.get('product'),age:+f.get('age'),sex:f.get('sex'),occupation:f.get('occupation'),cover:+f.get('cover'),bmi:+f.get('bmi'),smoker:f.get('smoker')==='true',condition:f.get('condition')});for(const key of Object.keys(extraAttributes)){const value=f.get(key);profile[key]=value===null||String(value).trim()===''?null:Number(value)}const instruction=String(f.get('customInstructions')||'').trim();if(instruction!==customInstructions)policyRevision++;customInstructions=instruction;if(mode==='mock')profile.evidence=f.get('evidence')==='on'}
async function api(path,body,signal){if(!['localhost','127.0.0.1','[::1]'].includes(location.hostname))throw Error('Open the local runner at http://127.0.0.1:8080 for real API testing. See Local API setup.');const r=await fetch('/api/'+path,{method:body?'POST':'GET',headers:body?{'Content-Type':'application/json'}:{},body:body?JSON.stringify({...body,policy:run?.policy||{rules:customRules,instructions:customInstructions,revision:policyRevision}}):undefined,signal:signal?AbortSignal.any([signal,AbortSignal.timeout(path==='reason'?210000:150000)]):AbortSignal.timeout(150000)});let d;try{d=await r.json()}catch{throw Error('The local Python runner is not available at this address.')}if(!r.ok)throw Error(d.error||'Local API request failed');return d}
async function stage(id,fn){const started=performance.now();run.steps[id]={status:'running',summary:stageHint(id)};render();try{controller.signal.throwIfAborted();if(mode==='mock')await new Promise((resolve,reject)=>{const t=setTimeout(resolve,600);controller.signal.addEventListener('abort',()=>{clearTimeout(t);reject(new DOMException('Cancelled','AbortError'))},{once:true})});const d=await fn();controller.signal.throwIfAborted();run.steps[id]={status:'done',summary:d.summary,data:d.data,duration_ms:Math.round(performance.now()-started)};log(stages.find(s=>s[0]===id)[1],d.summary);render();return d.data}catch(e){run.steps[id]={status:'error',summary:e.message};throw e}}
async function fileData(){return Promise.all(files.map(f=>new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve({name:f.name,type:f.type,data:String(reader.result).split(',')[1]});reader.onerror=()=>reject(Error('Could not read file '+f.name));reader.readAsDataURL(f)})))}
async function start(){if(busy)return;showScenarioSelection=false;busy=true;controller=new AbortController();run={started:new Date().toISOString(),route:'Screening',steps:{},result:null,policy:structuredClone({rules:customRules,instructions:customInstructions,revision:policyRevision}),customRuleResults:evaluateRules(profile,customRules)};render();requestAnimationFrame(()=>{const progress=document.querySelector('.pipeline-panel');if(progress){progress.setAttribute('tabindex','-1');progress.focus({preventScroll:true});progress.scrollIntoView({behavior:window.matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'start'});}});try{await stage('intake',async()=>{if(mode==='local'){await api('health',null,controller.signal);if(!files.length)throw Error('Upload at least one medical report or image for local testing.')}return {summary:'Inputs validated. '+(mode==='mock'?'Synthetic evidence selected.':files.length+' documents ready.'),data:{profile,documents:files.map(f=>({name:f.name,size:f.size})),mode}}});const ml=await stage('ml',async()=>{const d=mode==='mock'?mockML(profile):await api('ml',{profile,documents:await fileData()},controller.signal);return {summary:d.available?`Model ${d.model}: ${d.standard?'standard':'non-standard'}, confidence ${Math.round(d.confidence*100)}%, ${d.ood?'out-of-distribution':'in-distribution'}.`:'ML unavailable → guarded reasoning. '+(d.error||''),data:d}});const synthetic=mode==='mock'?prepareEvidence({...mockEvidence(profile,files),observations:syntheticObservations(profile,evidenceScenario)},profile):null;const complete=mode==='mock'?synthetic.complete:ml.evidence_complete===true;run.stpGates=gateChecks(profile,ml,complete,run.customRuleResults,customInstructions);const stp=run.stpGates.every(g=>g.pass);if(stp){run.route='ML · straight-through';if(synthetic)run.syntheticEvidence=synthetic;for(const id of ['evidence','context','reason'])run.steps[id]={status:'skipped',summary:'STP gate passed; complex reasoning not required.'};await stage('verify',async()=>({summary:'Standard class, calibration, confidence, OOD, evidence and referral gates passed.',data:{confidence:ml.confidence,threshold:.95,evidence_complete:complete,business_rules_passed:true,model:ml.model}}));await stage('decision',async()=>{run.result={status:'Standard acceptance',headline:'Eligible for straight-through processing',explanation:'The ML result and all configured STP gates passed.',reasons:[`Standard classification at ${Math.round(ml.confidence*100)}% model confidence.`,'Model reports calibration and an in-distribution application.',mode==='mock'?'Synthetic evidence is marked complete.':'Evidence completeness was certified by the ML adapter; Vision LLM analysis was skipped.','No mandatory business-rule referral matched.'],next:'Policy issuance handoff only; no policy is issued.',review:false};return {summary:'Standard acceptance recorded with gate results.',data:run.result}})}else{run.route='Vision LLM · complex path';const docs=mode==='local'?await fileData():[];const evidence=await stage('evidence',async()=>{const d=mode==='mock'?synthetic:prepareEvidence(await api('evidence',{profile,documents:docs},controller.signal),profile);return {summary:d.complete?'Evidence extracted with source attribution.':'Evidence gaps detected; automatic acceptance blocked.',data:d}});const context=await stage('context',async()=>{const d=mode==='mock'?mockContext():await api('context',{profile,findings:evidence.findings,observations:evidence.observations},controller.signal);return {summary:mode==='mock'?'Simulated internal, knowledge, external and web sources.':d.sources.length?`${d.sources.length} attributable sources retrieved.`:'No context adapter connected; enrichment unavailable.',data:d}});const reason=await stage('reason',async()=>{const d=mode==='mock'?{recommendation:evidence.complete&&policyOutcome(run.customRuleResults)!=='request_evidence'?'refer':'request_evidence',explanation:evidence.complete?'The application did not satisfy the strict ML fast-path gate. Evidence-led review is required.':'Evidence is incomplete or contains unresolved observations; review the decision brief before proceeding.',reasons:[profile.scenario==='ml_error'?'ML service failure triggered fallback.':referral(profile)?'Declared risk or coverage requires business-rule referral.':'STP gate did not pass.',evidence.findings[0].text],citations:['DOC-1','INT-1'],missing_information:evidence.complete?[]:evidence.observation_review?.issues.length?evidence.observation_review.issues.map(x=>x.text):['Complete medical report'],iterations:1,validation_errors:[],note:'Scripted reasoning, not a live LLM response.'}:await api('reason',{profile,evidence,context,ml},controller.signal);return {summary:`Structured recommendation: ${d.recommendation}. Harness iterations: ${d.iterations}.`,data:d}});const verified=await stage('verify',async()=>{const d=mode==='mock'?{passed:true,decision:evidence.complete&&policyOutcome(run.customRuleResults)!=='request_evidence'?'refer':'request_evidence',checks:['Schema valid','Source IDs valid','No autonomous complex-case approval'],warnings:['Illustrative controls only; no live safety model used.']}:await api('verify',{profile,evidence,context,reason},controller.signal);return {summary:d.passed?'Output validated; human review retained.':'Output failed verification; human review required.',data:d}});await stage('decision',async()=>{run.result={status:verified.decision==='request_evidence'?'Awaiting evidence':'Manual review',headline:verified.decision==='request_evidence'?'Request further supporting evidence':'An explained recommendation, ready for review',explanation:reason.explanation,reasons:[...reason.reasons,...(reason.missing_information||[]).map(x=>'Missing: '+x),...(!verified.passed?['Verification did not pass; do not rely on the recommendation.']:[])],sources:[...evidence.findings,...context.sources].filter(s=>(reason.citations||[]).includes(s.id)),next:verified.decision==='request_evidence'?'Obtain missing evidence and run a fresh assessment.':'Review evidence and record a human decision. No autonomous complex-case approval.',review:true};return {summary:'Assessment completed with reasons and next actions.',data:run.result}})}applyPolicyToResult();log('Assessment completed',run.route)}catch(e){const cancelled=e.name==='AbortError';run.result={status:cancelled?'Cancelled':'Failed',headline:cancelled?'Assessment cancelled':'Assessment stopped safely',explanation:cancelled?'No approval has been generated.':e.message,reasons:['No mock result has been substituted for an unsuccessful real model call.'],next:'Check inputs and local API connection, then re-run.',review:false};log('Assessment stopped',e.message)}finally{busy=false;render()}}
document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>{if(busy){toast('Wait for completion or cancel the assessment first.');return}view=b.dataset.view;render()});render();

function expandedAttributes(){return '<details class="extra-attributes"><summary>Financial, medical & evidence attributes</summary><p class="micro">Optional declared values, not verified findings. Leave unknown values blank. No clinical cut-offs are supplied.</p><div class="form-grid">'+Object.entries(extraAttributes).map(([key,a])=>'<label>'+esc(a.label)+'<input name="'+key+'" type="number" min="'+a.min+'" max="'+a.max+'" step="any" value="'+esc(profile[key]??'')+'"></label>').join('')+'</div></details>';}
function instructionsEditor(){return '<div class="instruction-box"><h3>Underwriter instructions</h3><label>Assessment focus<textarea name="customInstructions" maxlength="3000" placeholder="For example: Compare the chronology of declarations and reports. List missing evidence before discussing terms.">'+esc(customInstructions)+'</textarea></label><p class="micro">Non-empty instructions send the case to the reasoning path. They cannot authorise approval or bypass rules. Mock mode records the text; arbitrary free text is executed only by the local LLM.</p><button type="button" class="secondary" id="instruction-template">Use evidence-review template</button></div>';}
function advancedRulesView(){
 const r=customRules.find(x=>x.id===editingRule)||{title:'',field:'age',operator:'gte',value:60,action:'refer',scope:'Both'};
 const results=evaluateRules(profile,customRules);
 const impact=profiles.map(p=>{const out=policyOutcome(evaluateRules(p,customRules));return {name:p.name,baseline:eligible(p,mockML(p),p.evidence)?'STP':'Complex',after:out==='request_evidence'?'Evidence required':out==='refer'?'Custom referral':eligible(p,mockML(p),p.evidence)?'STP':'Complex'}});
 return '<div class="page-title"><div><span class="eyebrow">UNDERWRITER CONTROL · POLICY REVISION '+policyRevision+'</span><h1>Make your risk philosophy executable.</h1><p class="muted">Draft rules, inspect their effects and activate them for this demo session.</p></div><button class="secondary" id="export-policy">Export rules & instructions ↓</button></div><div class="governance-grid"><section class="panel setup-panel"><h2>'+(editingRule?'Edit custom rule':'Add a custom rule')+'</h2><form id="rule-form"><div class="form-grid"><label>Rule title<input name="title" required maxlength="120" value="'+esc(r.title)+'" placeholder="e.g. Senior case review"></label><label>Product scope<select name="scope">'+options(['Both','Life','Medical'],r.scope)+'</select></label><label>Attribute<select name="field">'+Object.entries(ruleFields).map(([key,a])=>'<option value="'+key+'" '+(r.field===key?'selected':'')+'>'+a.label+'</option>').join('')+'</select></label><label>Comparison<select name="operator">'+[['gt','Greater than'],['gte','At least'],['lt','Less than'],['lte','At most'],['eq','Equals'],['ne','Not equal']].map(([v,t])=>'<option value="'+v+'" '+(r.operator===v?'selected':'')+'>'+t+'</option>').join('')+'</select></label><label>Value<input name="value" required value="'+esc(r.value)+'" placeholder="Number, true / false, or declaration"></label><label>Action<select name="action">'+[['refer','Refer to underwriter'],['request_evidence','Request evidence'],['note','Add advisory note']].map(([v,t])=>'<option value="'+v+'" '+(r.action===v?'selected':'')+'>'+t+'</option>').join('')+'</select></label></div><p class="micro">Numeric comparisons use the displayed units. Smoking accepts true / false; declaration accepts none / controlled / complex. Rules cannot automatically approve or decline. Missing blocking-rule inputs require evidence.</p><button class="primary">'+(editingRule?'Save as new draft revision':'Create draft rule')+'</button></form><label class="spaced">Import saved policy JSON<input type="file" id="import-policy" accept=".json,application/json"></label><p class="micro">Import replaces session rules and instructions after validation. It does not represent production approval.</p></section><section class="panel setup-panel"><h2>Rule register</h2><p class="micro">Activation is a demo control, not a multi-user approval workflow.</p>'+ (customRules.length?customRules.map(rule=>{const result=results.find(x=>x.id===rule.id);return '<div class="custom-rule"><div class="section-heading"><strong>'+esc(rule.title)+'</strong>'+badge(rule.enabled?'Active':'Draft',rule.enabled?'green':'amber')+'</div><p>'+esc(ruleFields[rule.field].label)+' '+esc(rule.operator)+' '+esc(rule.value)+' → '+esc(rule.action)+'</p><small>'+rule.id+' · revision '+rule.revision+' · '+rule.scope+' · selected case: '+result.status+'</small><div class="button-row"><button class="secondary" data-edit-rule="'+rule.id+'">Edit</button><button class="secondary" data-toggle-rule="'+rule.id+'">'+(rule.enabled?'Deactivate':'Activate for demo')+'</button><button class="secondary" data-delete-rule="'+rule.id+'">Remove</button></div></div>'}).join(''):'<p class="empty">No custom rules yet. Built-in safety gates remain active.</p>')+'</section></div><section class="panel table-wrap spaced"><div class="setup-panel"><h2>Rule impact preview</h2><p class="micro">Six synthetic cases only. This is a routing comparison, not accuracy, fairness or outcome validation. Demographic edits in the studio do not alter these reference cases.</p></div><table><thead><tr><th>Reference case</th><th>Built-in route</th><th>With active custom rules</th></tr></thead><tbody>'+impact.map(x=>'<tr><td>'+x.name+'</td><td>'+x.baseline+'</td><td>'+x.after+'</td></tr>').join('')+'</tbody></table></section><details class="spaced"><summary>Built-in gates that custom rules cannot relax</summary>'+rulesView()+'</details>';
}
function trustView(){
 if(!run?.result)return '';
 const rows=run.customRuleResults||[];
 const evidence=run.steps.evidence?.data;
 return '<section class="panel result-panel"><span class="eyebrow">DECISION ASSURANCE</span><h2>What supports this result?</h2><div class="trust-grid">'+trustSummary(run,mode).map(([title,value,note])=>'<div><span>'+title+'</span><strong>'+esc(value)+'</strong><p>'+note+'</p></div>').join('')+'</div><h3>Straight-through gate explanation</h3><div class="gate-list">'+(run.stpGates||[]).map(g=>'<div><span>'+esc(g.label)+'</span>'+badge(g.pass?'Passed':'Not passed',g.pass?'green':'amber')+'</div>').join('')+'</div><h3>Custom rule trace</h3>'+(rows.length?'<div class="table-wrap"><table><thead><tr><th>Rule / revision</th><th>Observed input</th><th>Result</th></tr></thead><tbody>'+rows.map(r=>'<tr><td>'+esc(r.title)+' · v'+r.revision+'</td><td>'+esc(r.actual??'Unknown')+'</td><td>'+badge(r.status,r.blocks?'amber':'blue')+'</td></tr>').join('')+'</tbody></table></div>':'<p class="micro">No custom rules applied.</p>')+'<div class="note"><strong>Instructions captured with this run</strong><p>'+esc(run.policy?.instructions||'No custom instructions.')+'</p></div>'+(evidence?'<h3>Evidence review ledger</h3>'+evidence.findings.map((f,i)=>'<div class="evidence-review"><div><code>'+esc(f.id)+'</code> <strong>'+esc(f.source)+'</strong><p>'+esc(f.text)+'</p><small>Page: '+esc(f.page??'Not supplied')+' · '+(f.quote?'Quoted text supplied; verify against original':'No verbatim source quote supplied')+'</small>'+(f.quote?'<blockquote>'+esc(f.quote)+'</blockquote>':'')+'</div><label class="check"><input type="checkbox" data-reviewed="'+i+'" '+(run.reviewed?.includes(i)?'checked':'')+'> Source checked by reviewer</label></div>').join(''):'')+'<div class="button-row">'+files.map((f,i)=>'<button class="secondary" data-open-file="'+i+'">Open '+esc(f.name)+'</button>').join('')+'</div><p class="micro">Review marks record human inspection only; they do not change model confidence or remove referral gates. Policy snapshot and step timings are included in the assessment export.</p></section>';
}
function bindGovernance(){
 if($('#evidence-scenario'))$('#evidence-scenario').onchange=e=>{saveProfile();evidenceScenario=e.target.value;reset();render()};
 if($('#rule-form'))$('#rule-form').onsubmit=e=>{e.preventDefault();try{const f=new FormData(e.target),field=f.get('field'),type=ruleFields[field].type;let value=f.get('value').trim();if(type==='number')value=value===''?NaN:Number(value);if(type==='boolean'){if(!['true','false'].includes(value))throw Error('Smoking value must be true or false.');value=value==='true'}const prior=customRules.find(x=>x.id===editingRule);const r=validateRule({id:prior?.id||'USR-'+crypto.randomUUID(),revision:(prior?.revision||0)+1,title:f.get('title').trim(),scope:f.get('scope'),field,operator:f.get('operator'),value,action:f.get('action'),enabled:false});if(prior)customRules=customRules.map(x=>x.id===r.id?r:x);else{if(customRules.length>=50)throw Error('Maximum 50 custom rules.');customRules.push(r)}policyRevision++;editingRule=null;reset();log('Rule draft saved',r);render();toast('Draft saved. Inspect the rule, then activate for the demo.')}catch(err){toast(err.message)}};
 document.querySelectorAll('[data-edit-rule]').forEach(b=>b.onclick=()=>{editingRule=b.dataset.editRule;render()});
 document.querySelectorAll('[data-toggle-rule]').forEach(b=>b.onclick=()=>{const r=customRules.find(x=>x.id===b.dataset.toggleRule);r.enabled=!r.enabled;policyRevision++;reset();log('Rule status changed',{id:r.id,revision:r.revision,enabled:r.enabled});render()});
 document.querySelectorAll('[data-delete-rule]').forEach(b=>b.onclick=()=>{const id=b.dataset.deleteRule;customRules=customRules.filter(x=>x.id!==id);policyRevision++;reset();log('Rule removed',id);render()});
 if($('#export-policy'))$('#export-policy').onclick=()=>download({schema:'uw-policy-1',rules:customRules,instructions:customInstructions},'underwriting-policy.json');
 if($('#import-policy'))$('#import-policy').onchange=async e=>{try{const f=e.target.files[0];if(!f)return;if(f.size>100000)throw Error('Policy file exceeds 100 KB.');const b=validateBundle(JSON.parse(await f.text()));customRules=b.rules;customInstructions=b.instructions;policyRevision++;reset();log('Policy imported',{rules:customRules.length});render();toast('Policy imported for this session.')}catch(err){toast(err.message)}};
 if($('#instruction-template'))$('#instruction-template').onclick=()=>{saveProfile();customInstructions='Compare the chronology of declarations and supporting reports. Identify contradictions, missing evidence and source dates. Explain why each matched rule requires review. Do not infer missing values or suggest unsupported terms.';policyRevision++;reset();render()};
 document.querySelectorAll('[data-reviewed]').forEach(b=>b.onchange=()=>{run.reviewed=run.reviewed||[];const i=+b.dataset.reviewed;run.reviewed=run.reviewed.filter(x=>x!==i);if(b.checked)run.reviewed.push(i);log('Evidence review mark',{finding:i,checked:b.checked})});
 document.querySelectorAll('[data-open-file]').forEach(b=>b.onclick=()=>{const f=files[+b.dataset.openFile],u=URL.createObjectURL(f);const a=document.createElement('a');a.href=u+(b.dataset.page?'#page='+Number(b.dataset.page):'');a.target='_blank';a.rel='noopener';a.click();setTimeout(()=>URL.revokeObjectURL(u),60000)});
}
function applyPolicyToResult(){
 if(!run?.result)return;
 const out=policyOutcome(run.customRuleResults||[]);
 const reasons=(run.customRuleResults||[]).filter(r=>r.status==='matched'||r.status==='missing').map(r=>r.title+' [v'+r.revision+']: '+(r.status==='missing'?'Required input '+r.field+' is unknown.':r.field+' '+r.operator+' '+r.value+' matched (observed '+r.actual+').'));
 run.result.reasons.push(...reasons);
 if(out==='request_evidence'){run.result.status='Awaiting evidence';run.result.headline='Custom policy requires further evidence';run.result.next='Resolve the missing input or evidence requirement, then reassess.';}
 else if(out==='refer'&&run.result.status!=='Awaiting evidence'){run.result.status='Manual review';run.result.next='Review the matched custom rules and original evidence before recording a decision.';}
}


function researchView(){return '<div class="page-title"><div><span class="eyebrow">PRIMARY-SOURCE RESEARCH · 6 SEPTEMBER 2026</span><h1>Design decisions grounded in evidence.</h1></div></div><iframe title="Underwriting research report" src="research.html" class="research-frame"></iframe>';}

function evidenceScenarioPicker(){return '<label class="spaced">Evidence demonstration<select id="evidence-scenario">'+[['as_declared','Consistent measurements'],['conflict','Conflicting same-date results'],['missing_date','Missing measurement date'],['unknown_unit','Missing measurement unit'],['timeline','Earlier result differs from declaration']].map(([v,t])=>'<option value="'+v+'" '+(v===evidenceScenario?'selected':'')+'>'+t+'</option>').join('')+'</select></label><p class="micro">Synthetic documents only. Conflicts and unresolved observations block the mock fast path.</p>';}
function decisionBrief(){
 if(!run?.result)return '';
 const e=run.steps.evidence?.data||run.syntheticEvidence,review=e?.observation_review;
 const issues=review?.issues||[];
 const actions=issues.length?issues.map(x=>x.text):!e?['Review adapter-certified evidence. No document measurements were extracted in this run.']:!e.complete?['Obtain the outstanding evidence and reassess.']:['Inspect the original sources and applicable policy before any human decision.'];
 return '<section class="panel result-panel decision-brief"><span class="eyebrow">UNDERWRITER DECISION BRIEF</span><h2>'+esc(run.result.human?'Human decision recorded':run.result.status)+'</h2><p>'+esc(profile.name)+' · '+esc(profile.product)+' · Policy revision '+run.policy.revision+'</p><div class="brief-columns"><div><h3>What needs attention</h3><ul>'+actions.map(x=>'<li>'+esc(x)+'</li>').join('')+'</ul></div><div><h3>Decision basis</h3><p>'+esc(run.result.explanation)+'</p><p><strong>Next action:</strong> '+esc(run.result.next)+'</p><p class="micro">'+(mode==='mock'?'All observations below are synthetic.':'Extracted observations remain unverified. Source quotes are not proof of correctness.')+' No medical thresholds or clinical interpretations are inferred.</p></div></div>'+(review?'<h3>Measurements and chronology</h3><p class="micro">Dates are measurement dates. Differences from today’s declaration may reflect changes over time; resolve them before relying on the comparison.</p><div class="table-wrap"><table class="observation-table"><thead><tr><th>Date / field</th><th>Source value</th><th>Current declaration</th><th>Evidence</th></tr></thead><tbody>'+review.timeline.map(o=>'<tr><td>'+esc(o.observed_at||'Date unknown')+'<br><strong>'+esc(o.field)+'</strong></td><td>'+esc(o.raw_value)+' '+esc(o.raw_unit||'(unit unknown)')+'<br><small>'+esc(o.normalized_value===null?'Not normalized':'Unit validated; not clinically interpreted')+'</small></td><td>'+esc(profile[o.field]??'Unknown')+' '+esc(units[o.field])+'</td><td><details><summary>'+esc(o.source.document_id)+' · page '+o.source.page+' · '+esc(o.id)+'</summary>'+((mode==='local'&&files[Number(o.source.document_id.replace('DOC-',''))-1])?'<button type="button" class="secondary" data-open-file="'+(Number(o.source.document_id.replace('DOC-',''))-1)+'" data-page="'+o.source.page+'">Open source page</button>':'')+'<blockquote>'+esc(o.source.quote)+'</blockquote><p class="micro">'+esc(o.source.sha256?'Document hash: '+o.source.sha256:'Synthetic source')+'</p></details></td></tr>').join('')+'</tbody></table></div>':'')+'<p class="micro">A source-check mark does not resolve discrepancies. Correct the source or declaration and run a new assessment; prior results are invalidated.</p></section>';
}

function studio(){
 if(showScenarioSelection&&run?.result&&!busy)return '<button type="button" class="secondary" id="return-to-review">Return to assessment review</button>'+legacyStudio();
 if(!run?.result||busy)return legacyStudio();
 const {items,issues}=reviewItems(run),r=run.result;
 const selected=items.find(x=>x.key===selectedEvidence)||items.find(x=>issues.some(i=>i.targets.includes(x.key)))||items[0];
 const blocking=issues.filter(i=>i.blocking).length;
 const outcome=outcomeStyle(r);
 const checked=items.filter(x=>run.sourceChecks?.includes(x.key)).length;
 return `<button type="button" class="secondary" id="back-to-scenarios" style="margin-bottom:16px">← Back to scenarios</button><div class="review-header"><div><span class="eyebrow">CASE REVIEW · ${mode==='mock'?'SIMULATION':'LOCAL MODEL OUTPUT'}</span><h1>${esc(profile.name)}</h1><p>${esc(profile.product)} · ${profile.age} years · SGD ${Number(profile.cover).toLocaleString()} cover · Policy revision ${run.policy.revision}</p></div><span class="outcome-badge outcome-${outcome.tone}">${esc(outcome.label)}</span></div>
 <section class="review-summary panel outcome-${outcome.tone}" aria-label="Decision summary"><div><span class="eyebrow">${r.human?'RECORDED DECISION':'PROPOSED OUTCOME'}</span><h2>${esc(r.human?.outcome||r.headline)}</h2><p>${esc(r.human?.reason||r.explanation)}</p></div><div class="summary-metrics ${blocking?'has-blockers':''}"><strong>${blocking}</strong><span>Unresolved blocking items</span><strong>${checked} / ${items.length}</strong><span>Sources checked</span></div><div><strong>Next action</strong><p>${esc(r.next)}</p><a href="#review-actions">Go to decision controls</a></div></section>
 <details class="case-inputs"><summary>Case details, documents and reassessment</summary>${legacyStudio()}</details>
 <div class="review-layout"><section class="panel review-workspace" aria-label="Evidence review"><div class="review-nav" role="group" aria-label="Review sections">${[['issues','Issues first'],['timeline','Measurements & findings'],['basis','Reasons & policy']].map(([key,label])=>`<button type="button" data-review-tab="${key}" aria-pressed="${reviewTab===key}">${label}${key==='issues'?' ('+issues.length+')':''}</button>`).join('')}</div>
 <div class="review-split"><div class="review-findings" id="review-list" tabindex="-1">
 ${reviewTab==='issues'?`<h2>What needs attention</h2><p class="micro">Checking a source records inspection. Blocking items remain until the evidence or inputs are corrected and reassessed.</p>${issues.length?issues.map(i=>`<article class="review-issue ${i.blocking?'blocking':''}">${badge(i.blocking?'Blocking':'Advisory',i.blocking?'amber':'blue')}<p>${esc(i.text)}</p>${i.targets.filter(id=>items.some(x=>x.key===id)).map(id=>`<button type="button" class="secondary" data-select-evidence="${esc(id)}">Inspect ${esc(id)}</button>`).join('')}</article>`).join(''):'<p class="empty">No blocking items were identified by the configured checks. This does not establish clinical completeness.</p>'}<button type="button" class="secondary" data-review-tab="timeline">Review all evidence</button>`:''}
 ${reviewTab==='timeline'?`<h2>Measurements & findings</h2><p class="micro">Measurements are ordered by date; undated findings follow. Values are not clinical interpretations.</p>${items.length?items.map(item=>`<button type="button" class="evidence-choice ${selected?.key===item.key?'selected':''}" data-select-evidence="${esc(item.key)}" aria-pressed="${selected?.key===item.key}"><span>${esc(item.date||'Date not supplied')} · ${esc(item.key)}</span><strong>${esc(item.label)}</strong><span>${esc(item.value||'')}</span><small>${run.sourceChecks?.includes(item.key)?'Source checked':'Extracted · unchecked'} · ${esc(item.source.document_id)} · page ${esc(item.source.page||'unknown')}</small></button>`).join(''):'<p>No extracted evidence in this run. The ML adapter certified the fast path; inspect its evidence outside this viewer.</p>'}`:''}
 ${reviewTab==='basis'?`<h2>Reasons and policy context</h2>${r.reasons.map(t=>`<p class="basis-reason">${esc(t)}</p>`).join('')}<h3>Sources cited by the recommendation</h3><p class="micro">These are recommendation-level citations. A citation alone does not establish support for every reason.</p>${(r.sources||[]).map(src=>`<article class="review-issue"><strong>${esc(src.title||src.source||src.id)}</strong><p>${esc(src.excerpt||src.text)}</p>${items.filter(item=>item.source.document_id===src.id).map(item=>`<button type="button" class="secondary" data-select-evidence="${esc(item.key)}">Inspect ${esc(item.key)}</button>`).join('')}${safeLink(src.url)}</article>`).join('')||'<p>No policy clauses were retrieved on the fast path. Review the configured gates in technical details.</p>'}`:''}
 </div><div class="review-document" id="source-panel" tabindex="-1">${sourcePanel(selected)}</div></div></section>
 <aside class="panel decision-controls" id="review-actions" tabindex="-1"><h2>Decision controls</h2><p>${blocking?blocking+' blocking item(s) remain. Recording a human decision does not clear them.':'Review the evidence and applicable policy before recording a decision.'}</p>
 ${r.review?`<form id="review-form"><label>Decision<select name="outcome">${options(['Approve standard terms','Propose revised terms','Request further evidence','Postpone','Decline'],run.reviewDraft?.outcome||'Request further evidence')}</select></label><label>Decision reason<textarea name="reason" required minlength="10" maxlength="1500" placeholder="Explain the evidence, policy and unresolved issues considered.">${esc(run.reviewDraft?.reason||'')}</textarea></label><button class="primary full">Record human decision</button></form>`:r.human?`<div class="note"><strong>${esc(r.human.outcome)}</strong><p>${esc(r.human.reason)}</p></div>`:'<p>No manual decision action is available for this result.</p>'}
 <button type="button" class="secondary full" id="export-result">Download assessment</button><p class="micro">Session record only. No policy is issued and no customer message is sent.</p></aside></div>
 <details class="technical-review"><summary>Technical details: assessment steps, confidence and rule checks</summary>${executionReview()}${trustView()}</details>`;
}
function sourcePanel(item){
 if(!item)return '<h2>Source viewer</h2><p>Select evidence to inspect its source. No document extraction was performed for this result.</p>';
 const index=mode==='local'?sourceFileIndex(item.source,files):-1;
 let document='';
 if(index>=0){const file=files[index];if(!reviewUrls.has(index))reviewUrls.set(index,URL.createObjectURL(file));const url=reviewUrls.get(index);
 document=file.type==='application/pdf'?`<object class="source-preview" data="${url}#page=${Number(item.source.page)||1}" type="application/pdf" aria-label="${esc(file.name)}"><p>Inline PDF preview is unavailable. Use Open original below.</p></object>`:`<img class="source-image" src="${url}" alt="Original uploaded document: ${esc(file.name)}">`;
 document+=`<a class="secondary" href="${url}#page=${Number(item.source.page)||1}" target="_blank" rel="noopener noreferrer">Open original in new tab</a><p class="micro">The viewer requests page ${esc(item.source.page||1)}. Confirm the page in your PDF viewer. Passage coordinates are not available for automatic highlighting.</p>`;
 }else document=mode==='mock'?`<div class="synthetic-page"><span class="eyebrow">SYNTHETIC SOURCE EXCERPT</span><h3>${esc(item.source.document_id)} · page ${esc(item.source.page||'unknown')}</h3><mark>${esc(item.source.quote||'No quoted passage supplied for this finding.')}</mark><p>This is fictional evidence for the demo, not an original medical report.</p></div>`:'<p>The original document is unavailable in this session. Re-upload it and reassess to review its source.</p>';
 return `<h2>Source evidence</h2><p><strong>${esc(item.key)}</strong> · ${esc(item.source.document_id)} · page ${esc(item.source.page||'unknown')}</p>${document}${mode==='local'?`<h3>Extracted source excerpt</h3><blockquote>${esc(item.source.quote||'No source excerpt supplied.')}</blockquote>`:''}<label class="check"><input type="checkbox" data-source-check="${esc(item.key)}" ${run.sourceChecks?.includes(item.key)?'checked':''}> Source checked by reviewer</label><label>Review note<textarea id="source-review-note" maxlength="1500" data-source-key="${esc(item.key)}" placeholder="Record observations or the clarification needed.">${esc(run.sourceNotes?.[item.key]||'')}</textarea></label><p class="micro">Notes and source checks are saved in this assessment export. They do not change evidence or the recommendation.</p>`;
}
function captureReviewDraft(){
 if(!run)return;
 const f=$('#review-form');if(f){const d=new FormData(f);run.reviewDraft={outcome:d.get('outcome'),reason:d.get('reason')};}
 const note=$('#source-review-note');if(note){run.sourceNotes=run.sourceNotes||{};run.sourceNotes[note.dataset.sourceKey]=note.value;}
}
function bindReviewWorkspace(){
 if($('#back-to-scenarios'))$('#back-to-scenarios').onclick=()=>{captureReviewDraft();showScenarioSelection=true;render();window.scrollTo(0,0);$('#profile')?.focus();};
 if($('#return-to-review'))$('#return-to-review').onclick=()=>{showScenarioSelection=false;render();window.scrollTo(0,0);$('#back-to-scenarios')?.focus();};
 document.querySelectorAll('[data-review-tab]').forEach(b=>b.onclick=()=>{captureReviewDraft();reviewTab=b.dataset.reviewTab;render();$('#review-list')?.focus();});
 document.querySelectorAll('[data-select-evidence]').forEach(b=>b.onclick=()=>{captureReviewDraft();selectedEvidence=b.dataset.selectEvidence;render();$('#source-panel')?.focus();});
 document.querySelectorAll('[data-source-check]').forEach(b=>b.onchange=()=>{captureReviewDraft();run.sourceChecks=(run.sourceChecks||[]).filter(id=>id!==b.dataset.sourceCheck);if(b.checked)run.sourceChecks.push(b.dataset.sourceCheck);log('Source inspection',{id:b.dataset.sourceCheck,checked:b.checked});render();$('#source-panel')?.focus();});
 const note=$('#source-review-note');if(note)note.oninput=captureReviewDraft;
 const exportButton=$('#export-result');if(exportButton)exportButton.onclick=()=>{captureReviewDraft();download({...run,profile,mode,files:files.map(f=>({name:f.name,size:f.size}))},'hybrid-assessment.json');};
}

function executionReview(){return '<section class="setup-panel"><h2>Assessment steps</h2>'+stages.map(([id,title])=>{const step=run.steps[id];return '<details class="review-issue"><summary>'+esc(title)+' · '+esc(step?.status||'Not run')+'</summary><p>'+esc(step?.summary||'No output')+'</p>'+(step?.data?'<pre>'+esc(JSON.stringify(step.data,null,2))+'</pre>':'')+'</details>';}).join('')+'</section>';}

function outcomeStyle(result){
 const label=result.human?.outcome||result.status;
 const tones={'Standard acceptance':'accepted','Approve standard terms':'accepted','Awaiting evidence':'evidence','Request further evidence':'evidence','Manual review':'review','Propose revised terms':'terms','Postpone':'postponed','Decline':'declined','Failed':'failed','Cancelled':'cancelled'};
 return {label:label||'Not assessed',tone:tones[label]||'cancelled'};
}
